    catAcidityAndBasicity: string; // Catalyst acidity and basicity
    catMetalOxidationStates: { // Array of metal oxidation states
        metal: string; // Metal name
        oxidationState: number; // Oxidation state
        proportion: string; // Proportion of the metal
    }[];
}

// Interface to represent the details of the reaction conditions
